// n8n Code node: "Build Search Requests"
// MODE: Run Once for All Items   LANGUAGE: JavaScript
//
// Fans the query planner's output into one item per Europe PMC search, so the
// HTTP Request node that follows runs once per query.
//
// Search is deliberately NOT an agent tool here. In the original workflow the
// writers held the search tools themselves, which meant the model decided what
// evidence existed, how much to look for, and when to stop -- and could simply
// not call them. Making the search a plain, always-executed HTTP step removes
// that discretion entirely.

// An Agent carrying a structured output parser nests its parsed object under
// `output`: $json.output.queries, NOT $json.queries. Reading the top level
// yields [] silently and trips the guard below -- which is how a planner that
// returned ten perfectly good queries was reported as returning none
// (sub-execution 149). The top-level fallback keeps pinned fixtures and any
// parser-less variant working.
const planned = $input.first().json || {};
const parsed =
  planned.output && typeof planned.output === 'object' ? planned.output : planned;
const queries = Array.isArray(parsed.queries) ? parsed.queries : [];

const clean = [];
const seen = {};
for (const q of queries) {
  const t = String(q || '').replace(/\s+/g, ' ').trim();
  if (t.length < 3) continue;
  const k = t.toLowerCase();
  if (seen[k]) continue;
  seen[k] = true;
  clean.push(t);
}

if (!clean.length) {
  throw new Error(
    'Query planner returned no usable search queries. Refusing to continue: ' +
      'writing chapters without an evidence pack is exactly the failure mode this workflow exists to prevent.'
  );
}

// Cap the fan-out so a runaway planner cannot spray the API.
return clean.slice(0, 10).map((query) => ({ json: { query } }));

// n8n Code node: "Dedupe & Rank Candidates"
// MODE: Run Once for All Items   LANGUAGE: JavaScript
//
// Turns the raw Europe PMC search responses into the canonical evidence-record
// shape, deduplicates them, ranks them, caps the set, and assigns the stable
// ref_id (E01, E02, ...) that every writer must cite by.
//
// The ref_id is the load-bearing idea of this workflow: writers never see or
// write an author-year string, so they cannot invent one. They emit [E07], and
// the Citation Gate is the only thing that can turn that into a citation.
//
// A record with no abstract is dropped outright. An abstract is the minimum
// evidence needed to say anything about a study, and admitting a bare
// title+DOI is precisely what forced the old workflow to fabricate.
//
// Input  : $input.all() -> one item per search query, each a Europe PMC response
//          $('A0 Query Planner').first().json.output.year_floor
// Output : one item per surviving candidate.

const MAX_CANDIDATES = 30;
const DEFAULT_YEAR_FLOOR = new Date().getFullYear() - 10;

let yearFloor = DEFAULT_YEAR_FLOOR;
try {
  // Same nesting as Build Search Requests: the agent's parsed object lives
  // under `output`. Falling through to the top level keeps test fixtures and
  // pinned data working.
  const pj = $('A0 Query Planner').first().json || {};
  const src = pj.output && typeof pj.output === 'object' ? pj.output : pj;
  const planned = Number(src.year_floor);
  if (planned && planned > 1900 && planned <= new Date().getFullYear()) yearFloor = planned;
} catch (e) {
  // planner unavailable in isolated tests; default stands
}

// ------------------------------------------------------------- normalise ----
function norm(raw) {
  const ji = raw.journalInfo || {};
  const journal = ji.journal || {};
  const authors = ((raw.authorList || {}).author || []).map((a) => ({
    lastName: a.lastName || null,
    firstName: a.firstName || null,
    initials: a.initials || null,
    fullName: a.fullName || a.collectiveName || null,
  }));

  const year = parseInt(raw.pubYear || ji.yearOfPublication, 10) || null;

  return {
    ref_id: null, // assigned after ranking
    source_id: raw.id || null,
    pmid: raw.pmid || null,
    pmcid: raw.pmcid || null,
    doi: raw.doi || null,
    title: (raw.title || '').replace(/\s+/g, ' ').replace(/\.$/, '').trim(),
    authors,
    year,
    journal: journal.title || journal.medlineAbbreviation || null,
    volume: ji.volume || null,
    issue: ji.issue || null,
    pages: raw.pageInfo || null,
    abstract: (raw.abstractText || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
    pub_types: ((raw.pubTypeList || {}).pubType || []).map((t) => String(t).toLowerCase()),
    cited_by: parseInt(raw.citedByCount, 10) || 0,
    oa: raw.isOpenAccess === 'Y' && !!raw.pmcid,
  };
}

// --------------------------------------------------------------- gather ----
const raw = [];
for (const item of $input.all()) {
  const body = item.json || {};
  const list = ((body.resultList || {}).result) || [];
  for (const r of list) raw.push(r);
}

// ------------------------------------------------ filter, dedupe, rank ----
const EXCLUDE_TYPES = ['retracted publication', 'retraction of publication', 'comment', 'editorial'];

function keyOf(rec) {
  if (rec.doi) return 'doi:' + String(rec.doi).toLowerCase();
  if (rec.pmid) return 'pmid:' + rec.pmid;
  return 'ttl:' + rec.title.toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 60);
}

const seen = new Map();
for (const r of raw) {
  const rec = norm(r);
  if (!rec.title || !rec.abstract) continue;          // no abstract -> no evidence
  if (!rec.year || rec.year < yearFloor) continue;
  if (rec.pub_types.some((t) => EXCLUDE_TYPES.includes(t))) continue;

  const k = keyOf(rec);
  const prev = seen.get(k);
  // On a duplicate keep the richer record (OA beats non-OA, longer abstract wins).
  if (!prev || (rec.oa && !prev.oa) || rec.abstract.length > prev.abstract.length) {
    seen.set(k, rec);
  }
}

const thisYear = new Date().getFullYear();
function score(rec) {
  let s = 0;
  if (rec.pub_types.includes('research-article')) s += 5;
  if (rec.oa) s += 4;                                  // OA == methods & results are retrievable
  s += Math.max(0, 6 - (thisYear - rec.year)) * 0.8;   // recency
  s += Math.min(4, Math.log10(rec.cited_by + 1) * 2);  // influence, damped
  if (rec.abstract.length > 900) s += 1;
  return s;
}

const ranked = Array.from(seen.values())
  .map((rec) => ({ rec, s: score(rec) }))
  .sort((a, b) => b.s - a.s || (b.rec.year || 0) - (a.rec.year || 0))
  .slice(0, MAX_CANDIDATES)
  .map((x, i) => {
    x.rec.ref_id = 'E' + String(i + 1).padStart(2, '0');
    x.rec.rank_score = Math.round(x.s * 100) / 100;
    return x.rec;
  });

return ranked.map((json) => ({ json }));

// n8n Code node: "Fetch & Extract Full Text"
// MODE: Run Once for All Items   LANGUAGE: JavaScript
//
// Pulls Europe PMC open-access full text for every candidate that has one, and
// extracts the Methods and Results sections verbatim.
//
// This node is why the empirical review no longer has to invent study details.
// Previously the writers were asked for design / sample size / instruments /
// analysis / findings while being given nothing but titles and DOIs. Here those
// facts are fetched from the actual paper, and anything the paper does not
// report is simply left absent — never filled in.
//
// A Code node (rather than an HTTP Request node) is deliberate: this is N
// parallel fetches plus XML sectioning plus a merge back onto the candidate
// records. Doing it natively would need a split, an IF, a per-item HTTP node
// and an index-fragile re-join. One node with explicit per-record error
// handling is both simpler and safer.
//
// Input  : $input.all() -> candidate records from "Dedupe & Rank Candidates"
// Output : the same records, each gaining methods_text / results_text /
//          fulltext_status.

const EPMC = 'https://www.ebi.ac.uk/europepmc/webservices/rest';
const CONCURRENCY = 4; // be polite to EBI
const MAX_SECTION_CHARS = 4000;

// ------------------------------------------------------------ XML helpers ----

// Elements whose text must never reach a writer:
//  - xref  : renders as bare "12", which looks like a citation we did not issue
//  - table-wrap / fig / formulae / supplementary : layout noise, not prose
const DROP_ELEMENTS = [
  'xref',
  'table-wrap',
  'fig',
  'disp-formula',
  'inline-formula',
  'supplementary-material',
  'graphic',
  'media',
  'label',
];

function dropElements(xml) {
  let out = xml;
  for (const el of DROP_ELEMENTS) {
    // paired form
    out = out.replace(new RegExp(`<${el}\\b[^>]*>[\\s\\S]*?</${el}>`, 'gi'), ' ');
    // self-closing / empty form
    out = out.replace(new RegExp(`<${el}\\b[^>]*/?>`, 'gi'), ' ');
  }
  return out;
}

function decodeEntities(s) {
  return s
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#x2019;/g, '’')
    .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(parseInt(d, 10)))
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/&amp;/g, '&');
}

// The source paper's own in-text citations must not survive into our evidence
// text. They point at works that are NOT in our evidence pack, so a writer who
// copies one would produce a citation the gate cannot resolve. Stripping <xref>
// also leaves husks like "(Mackenzie & Knipe, )" with the year removed, which is
// worse than useless. Remove the whole parenthetical.
//
// Written as a regex literal + .source so there is no double-escaping to get
// wrong. Deliberately narrow: it requires Capitalised-surname + comma, so real
// data in parentheses -- (n = 32), (95% CI 1.2-3.4), (SD 1.2), (Table 1) -- is
// left untouched.
const CITE_ITEM =
  /[A-Z][A-Za-z'\u2019\-]+(?:\s+(?:et\s+al\.?|(?:&|and)\s+[A-Z][A-Za-z'\u2019\-]+))*\s*,\s*(?:(?:19|20)\d{2}[a-z]?)?/
    .source;
const CITE_PAREN = new RegExp(
  String.raw`\(\s*` + CITE_ITEM + String.raw`(?:\s*;\s*` + CITE_ITEM + String.raw`)*\s*\)`,
  'g'
);

function stripSourceCitations(str) {
  return str
    .replace(CITE_PAREN, ' ')
    .replace(/\(\s*[,;]\s*\)/g, ' ')  // husks left behind
    .replace(/\(\s*\)/g, ' ')
    .replace(/\s+([.,;:])/g, '$1')
    .replace(/[ \t\u00a0]{2,}/g, ' ');
}

// Tags out, paragraph structure preserved.
function toText(xml) {
  let s = dropElements(xml);
  s = s.replace(/<\/(p|title|sec|abstract)>/gi, '\n\n');
  s = s.replace(/<[^>]+>/g, ' ');
  s = decodeEntities(s);
  s = stripSourceCitations(s);
  return s
    .replace(/[ \t ]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// Depth-aware scan for top-level <sec> blocks inside a container.
// Nested subsections (e.g. Methods > Study design > Sampling) stay INSIDE their
// parent, which is what we want — the whole methods section, not its first line.
function topLevelSections(xml) {
  const secs = [];
  const re = /<sec\b[^>]*?\/>|<sec\b[^>]*>|<\/sec\s*>/gi;
  let m;
  let depth = 0;
  let start = -1;
  while ((m = re.exec(xml)) !== null) {
    const tag = m[0];
    if (/^<sec\b[^>]*\/>$/i.test(tag)) continue; // self-closing, no content
    if (tag[1] === '/') {
      depth--;
      if (depth === 0 && start >= 0) {
        secs.push(xml.slice(start, m.index + tag.length));
        start = -1;
      }
      if (depth < 0) depth = 0;
    } else {
      if (depth === 0) start = m.index;
      depth++;
    }
  }
  return secs;
}

function sectionTitle(secXml) {
  const m = secXml.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  return m ? toText(m[1]).replace(/\s+/g, ' ').trim() : '';
}

function sectionType(secXml) {
  const m = secXml.match(/^<sec\b[^>]*\bsec-type\s*=\s*"([^"]*)"/i);
  return m ? m[1].toLowerCase() : '';
}

const METHODS_RE =
  /^(materials?\s*(and|&)\s*methods?|methods?(\s*(and|&)\s*materials?)?|methodology|research\s+methods?(\s+and\s+design)?|patients?\s*(and|&)\s*methods?|subjects?\s*(and|&)\s*methods?|study\s+design(\s+and\s+methods?)?|experimental(\s+(section|methods?|procedures?))?|design\s+and\s+methods?)\b/i;

const RESULTS_RE = /^(results?|findings?|results?\s*(and|&)\s*discussion)\b/i;

function matchSections(sections, re, typeKeys) {
  const hits = [];
  for (const sec of sections) {
    const title = sectionTitle(sec);
    const stype = sectionType(sec);
    if ((title && re.test(title)) || (stype && typeKeys.includes(stype))) {
      hits.push(sec);
    }
  }
  return hits;
}

// Pull Methods / Results from the article body; fall back to a structured
// abstract when the body is unavailable or unsectioned.
function extractSections(xml) {
  const bodyMatch = xml.match(/<body\b[^>]*>([\s\S]*?)<\/body>/i);
  const absMatch = xml.match(/<abstract\b[^>]*>([\s\S]*?)<\/abstract>/i);

  const result = { methods_text: '', results_text: '', source: 'none' };

  const harvest = (container, label) => {
    const secs = topLevelSections(container);
    if (!secs.length) return false;
    const m = matchSections(secs, METHODS_RE, ['methods', 'materials|methods']);
    const r = matchSections(secs, RESULTS_RE, ['results']);
    if (!m.length && !r.length) return false;
    if (m.length) result.methods_text = m.map(toText).join('\n\n');
    if (r.length) result.results_text = r.map(toText).join('\n\n');
    result.source = label;
    return true;
  };

  if (bodyMatch && harvest(bodyMatch[1], 'body')) {
    // body won
  } else if (absMatch) {
    harvest(absMatch[1], 'structured-abstract');
  }

  for (const k of ['methods_text', 'results_text']) {
    if (result[k].length > MAX_SECTION_CHARS) {
      result[k] = result[k].slice(0, MAX_SECTION_CHARS).replace(/\s\S*$/, '') + ' […]';
    }
  }
  return result;
}

// ------------------------------------------------------------------ main ----
const records = $input.all().map((i) => i.json);

async function fetchOne(rec) {
  if (!rec.pmcid || rec.oa !== true) {
    return Object.assign({}, rec, {
      methods_text: '',
      results_text: '',
      fulltext_status: 'not_open_access',
    });
  }
  try {
    const xml = await this.helpers.httpRequest({
      method: 'GET',
      url: `${EPMC}/${rec.pmcid}/fullTextXML`,
      json: false,
      timeout: 30000,
      headers: { Accept: 'application/xml' },
    });
    const sections = extractSections(String(xml || ''));
    return Object.assign({}, rec, {
      methods_text: sections.methods_text,
      results_text: sections.results_text,
      fulltext_status:
        sections.methods_text || sections.results_text
          ? `ok:${sections.source}`
          : 'fetched_no_sections',
    });
  } catch (err) {
    // A failed fetch must never fabricate content — it just yields less evidence.
    return Object.assign({}, rec, {
      methods_text: '',
      results_text: '',
      fulltext_status: `error:${(err && err.message ? err.message : String(err)).slice(0, 120)}`,
    });
  }
}

const boundFetch = fetchOne.bind(this);
const out = [];
for (let i = 0; i < records.length; i += CONCURRENCY) {
  const batch = records.slice(i, i + CONCURRENCY);
  const settled = await Promise.all(batch.map(boundFetch));
  out.push(...settled);
}

return out.map((json) => ({ json }));

// n8n Code node: "Build Evidence Pack"
// MODE: Run Once for All Items   LANGUAGE: JavaScript
//
// Final assembly of the evidence the writers are allowed to use, and the ONLY
// thing they are given. No writer has a search tool; no writer has memory. If a
// fact is not in this pack, there is nowhere for it to come from except the
// model's imagination -- which is what the Citation Gate then catches.
//
// Produces three things:
//   evidence        - the structured array (consumed by the Citation Gate)
//   brief_pack      - abstract-level rendering for Chapter 1 / conceptual review
//   empirical_pack  - methods+results rendering for the empirical review, and
//                     ONLY for records that actually have them
//
// The empirical split is the fix for the original workflow's worst defect: it
// asked for study design, sample size, instruments and findings for 10-15
// studies while supplying nothing but titles and DOIs. Here a study can only
// reach the empirical writer if the paper genuinely reported those things.

const MAX_ABSTRACT = 1600;
const MAX_METHODS = 2500;
const MAX_RESULTS = 2500;
const MAX_EMPIRICAL_STUDIES = 15;

const records = $input.all().map((i) => i.json);

function clip(s, n) {
  const t = (s || '').trim();
  if (t.length <= n) return t;
  return t.slice(0, n).replace(/\s\S*$/, '') + ' […]';
}

function authorLine(rec) {
  const names = (rec.authors || [])
    .map((a) => {
      const sn = a.lastName || a.fullName || '';
      const ini = (a.initials || '').replace(/[.\s]/g, '');
      return sn ? (ini ? `${sn} ${ini}` : sn) : '';
    })
    .filter(Boolean);
  if (!names.length) return 'Unknown author';
  if (names.length <= 6) return names.join(', ');
  return names.slice(0, 6).join(', ') + ', et al.';
}

function header(rec) {
  const bits = [`[${rec.ref_id}] ${authorLine(rec)} (${rec.year || 'n.d.'}). ${rec.title}.`];
  if (rec.journal) bits.push(`Journal: ${rec.journal}${rec.volume ? ', ' + rec.volume : ''}.`);
  if (rec.doi) bits.push(`DOI: ${rec.doi}.`);
  else if (rec.pmid) bits.push(`PMID: ${rec.pmid}.`);
  return bits.join(' ');
}

// ------------------------------------------------------------- brief pack ----
const brief = records
  .map((rec) => `${header(rec)}\nABSTRACT: ${clip(rec.abstract, MAX_ABSTRACT)}`)
  .join('\n\n---\n\n');

// --------------------------------------------------------- empirical pack ----
// Admission test: a primary study that actually reported methods or results.
const NON_EMPIRICAL = ['review', 'systematic review', 'meta-analysis', 'case reports', 'editorial', 'comment'];

// Europe PMC types many reviews as 'research-article', so pub_types alone lets
// secondary literature into the empirical review. The title is the reliable
// signal. A review has no primary sample of its own to report.
const REVIEW_TITLE = /\b(?:systematic|narrative|scoping|integrative|umbrella|literature|rapid)\s+review\b|\bmeta[- ]analys/i;

const empiricalRecs = records
  .filter((rec) => {
    const hasEvidence = (rec.methods_text || '').length > 200 || (rec.results_text || '').length > 200;
    const isPrimary =
      rec.pub_types.includes('research-article') ||
      !rec.pub_types.some((t) => NON_EMPIRICAL.includes(t));
    const isReview = REVIEW_TITLE.test(rec.title || '');
    return hasEvidence && isPrimary && !isReview;
  })
  .sort((a, b) => (b.year || 0) - (a.year || 0)) // chronological descending, as the chapter requires
  .slice(0, MAX_EMPIRICAL_STUDIES);

const empirical = empiricalRecs
  .map((rec) => {
    const parts = [header(rec)];
    if (rec.abstract) parts.push(`ABSTRACT: ${clip(rec.abstract, MAX_ABSTRACT)}`);
    if (rec.methods_text) parts.push(`METHODS (verbatim from the paper):\n${clip(rec.methods_text, MAX_METHODS)}`);
    if (rec.results_text) parts.push(`RESULTS (verbatim from the paper):\n${clip(rec.results_text, MAX_RESULTS)}`);
    return parts.join('\n');
  })
  .join('\n\n---\n\n');

// -------------------------------------------------------------- statistics ----
const stats = {
  candidates: records.length,
  with_fulltext: records.filter((r) => (r.methods_text || r.results_text || '').length > 0).length,
  empirical_studies: empiricalRecs.length,
  open_access: records.filter((r) => r.oa).length,
  year_range: records.length
    ? `${Math.min(...records.map((r) => r.year || 9999))}-${Math.max(...records.map((r) => r.year || 0))}`
    : 'n/a',
  fulltext_failures: records.filter((r) => String(r.fulltext_status || '').startsWith('error:')).length,
};

return [
  {
    json: {
      evidence: records,
      brief_pack: brief,
      empirical_pack: empirical,
      empirical_ref_ids: empiricalRecs.map((r) => r.ref_id),
      stats,
    },
  },
];

